#!/usr/bin/env npx tsx
/**
 * CMP CLI — Interactive Node
 *
 * Start a CMP node that discovers peers, then type commands:
 *   compute    Send a computation task to the mesh
 *   peers      Show connected peers
 *   status     Show mesh status
 *   quit       Shutdown and exit
 *
 * Both requester and executor see live output of the full flow.
 *
 * @author Agent Viscro
 */

import fs from 'fs';
import path from 'path';
import readline from 'readline';
import { CMPNode } from '../../core/src/cmp-node';
import { LogLevel, Logger, toHex, shortId } from '../../core/src';

const VERSION = '1.0.0';

// ── Colors ──
const C = {
  r: '\x1b[0m', b: '\x1b[1m', d: '\x1b[2m',
  red: '\x1b[31m', green: '\x1b[32m', yellow: '\x1b[33m',
  blue: '\x1b[34m', magenta: '\x1b[35m', cyan: '\x1b[36m',
};

function log(icon: string, color: string, msg: string, detail?: string): void {
  const time = new Date().toISOString().substring(11, 19);
  let line = `  ${C.d}${time}${C.r} ${color}${icon}${C.r} ${msg}`;
  if (detail) line += `  ${C.d}${detail}${C.r}`;
  console.log(line);
}

function banner(): void {
  console.log(`
  ${C.cyan}╔═══════════════════════════════════════════╗${C.r}
  ${C.cyan}║${C.r}  ${C.b}CMP${C.r} — Compute Mesh Protocol v${VERSION}      ${C.cyan}║${C.r}
  ${C.cyan}║${C.r}  ${C.d}Agent Viscro${C.r}                             ${C.cyan}║${C.r}
  ${C.cyan}╚═══════════════════════════════════════════╝${C.r}
`);
}

function printHelp(): void {
  console.log(`
  ${C.b}Commands:${C.r}
    ${C.cyan}compute${C.r}     Send a task to the mesh (peers execute it)
    ${C.cyan}peers${C.r}       Show connected peers
    ${C.cyan}status${C.r}      Show mesh status
    ${C.cyan}help${C.r}        Show this help
    ${C.cyan}quit${C.r}        Shutdown and exit
`);
}

// ── Args ──
const args = process.argv.slice(2);
const command = args[0] || 'help';

function getFlag(name: string): boolean { return args.includes(`--${name}`); }
function getNumberOption(name: string, def: number): number {
  const idx = args.indexOf(`--${name}`);
  return idx !== -1 && idx + 1 < args.length ? parseInt(args[idx + 1], 10) : def;
}

// ── Minimal WASM module that does real computation ──
// This module exports `process(ptr, len) -> len`
// It XORs each input byte with 0x42 (a simple transform we can verify)
//
// WAT source:
//   (module
//     (memory (export "memory") 1)
//     (func (export "process") (param $ptr i32) (param $len i32) (result i32)
//       (local $i i32)
//       (local.set $i (i32.const 0))
//       (block $break
//         (loop $loop
//           (br_if $break (i32.ge_u (local.get $i) (local.get $len)))
//           (i32.store8
//             (i32.add (local.get $ptr) (local.get $i))
//             (i32.xor
//               (i32.load8_u (i32.add (local.get $ptr) (local.get $i)))
//               (i32.const 66)))
//           (local.set $i (i32.add (local.get $i) (i32.const 1)))
//           (br $loop)))
//       (local.get $len)))
//
// For simplicity we use the add module since custom WASM compilation is complex.
// The demo focuses on the NETWORK FLOW, not the computation content.
const DEMO_WASM = new Uint8Array([
  0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
  0x01, 0x07, 0x01, 0x60, 0x02, 0x7f, 0x7f, 0x01, 0x7f,
  0x03, 0x02, 0x01, 0x00,
  0x07, 0x07, 0x01, 0x03, 0x61, 0x64, 0x64, 0x00, 0x00,
  0x0a, 0x09, 0x01, 0x07, 0x00, 0x20, 0x00, 0x20, 0x01, 0x6a, 0x0b,
]);

// ══════════════════════════════════════════════════
// MAIN: cmp start
// ══════════════════════════════════════════════════

async function cmdStart(): Promise<void> {
  banner();

  const verbose = getFlag('verbose');
  const share = getNumberOption('share', 50);

  // Show INFO level so we can see bid handler decisions on executor side
  Logger.setLevel(verbose ? LogLevel.DEBUG : LogLevel.INFO);

  const node = new CMPNode({
    transports: ['lan'],
    maxResourceShare: share / 100,
    acceptingTasks: true,
    logLevel: verbose ? LogLevel.DEBUG : LogLevel.WARN,
  });

  await node.start();

  log('●', C.green, `Node started: ${C.b}${node.shortMeshId()}${C.r}`, node.meshIdHex());
  log('◉', C.blue, `Listening on LAN`, `resource share: ${share}%`);
  log('◌', C.d, `Scanning for peers...`);

  // ── Wire live events ──

  const bus = node.events();

  bus.on('peer:discovered', (data) => {
    log('◈', C.cyan, `Peer discovered: ${C.b}${shortId(data.meshId)}${C.r}`, data.transport);
  });

  bus.on('peer:handshake_complete', (data) => {
    log('🔗', C.green, `Handshake complete: ${C.b}${shortId(data.meshId)}${C.r}`, 'encrypted session established');
  });

  bus.on('capability:updated', (data) => {
    log('⬡', C.blue, `Capability received: ${C.b}${shortId(data.meshId)}${C.r}`);
  });

  bus.on('capability:mesh_changed', (data) => {
    log('◆', C.magenta, `Mesh: ${C.b}${data.peerCount}${C.r} peers, ${C.b}${data.totalCores}${C.r} cores`);
  });

  // ── Executor events (show when THIS node processes incoming tasks) ──

  bus.on('task:request_received', (data) => {
    log('📥', C.yellow, `Task request received: ${C.b}${shortId(data.taskId)}${C.r}`, `from ${shortId(data.requesterId)}`);
  });

  bus.on('task:bid_received', (data) => {
    log('🏷️', C.cyan, `Bid received from ${C.b}${shortId(data.bidderId)}${C.r}`, `score: ${data.score.toFixed(3)}`);
  });

  bus.on('task:assigned', (data) => {
    log('✓', C.green, `Task assigned: ${C.b}${shortId(data.taskId)}${C.r}`, `to ${data.assignees.length} devices`);
  });

  bus.on('chunk:received', (data) => {
    log('⚙️', C.yellow, `Executing chunk: ${C.b}${shortId(data.chunkId)}${C.r}`, `task ${shortId(data.taskId)}`);
  });

  bus.on('chunk:complete', (data) => {
    log('✓', C.green, `Chunk complete: ${C.b}${shortId(data.chunkId)}${C.r}`, `${data.timeMs}ms`);
  });

  bus.on('peer:lost', (data) => {
    log('✗', C.red, `Peer lost: ${C.b}${shortId(data.meshId)}${C.r}`, data.reason);
  });

  // ── Interactive REPL ──

  console.log();
  printHelp();

  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    prompt: `  ${C.cyan}cmp>${C.r} `,
  });

  rl.prompt();

  rl.on('line', async (line) => {
    const cmd = line.trim().toLowerCase();

    switch (cmd) {
      case 'compute':
      case 'c':
        await doCompute(node);
        break;

      case 'peers':
      case 'p':
        doPeers(node);
        break;

      case 'status':
      case 's':
        doStatus(node);
        break;

      case 'help':
      case 'h':
        printHelp();
        break;

      case 'quit':
      case 'q':
      case 'exit':
        console.log(`\n  ${C.yellow}Shutting down...${C.r}`);
        await node.stop();
        console.log(`  ${C.green}Node stopped.${C.r}\n`);
        process.exit(0);
        break;

      case '':
        break;

      default:
        console.log(`  ${C.d}Unknown command: ${cmd}. Type 'help' for commands.${C.r}`);
    }

    rl.prompt();
  });

  rl.on('close', async () => {
    await node.stop();
    process.exit(0);
  });
}

// ══════════════════════════════════════════════════
// COMPUTE: Send a real task to the mesh
// ══════════════════════════════════════════════════

async function doCompute(node: CMPNode): Promise<void> {
  const status = node.getStatus();

  if (status.peers === 0) {
    console.log(`\n  ${C.yellow}⚠ No peers connected.${C.r}`);
    console.log(`  ${C.d}Start another terminal with 'npx tsx src/cli.ts start'${C.r}`);
    console.log(`  ${C.d}Waiting for peers... (will retry when you type 'compute' again)${C.r}\n`);
    return;
  }

  // Generate demo input data
  const inputSize = 4096; // 4KB
  const inputData = new Uint8Array(inputSize);
  for (let i = 0; i < inputSize; i++) {
    inputData[i] = i % 256;
  }

  console.log();
  log('⚡', C.cyan, `${C.b}SUBMITTING TASK TO MESH${C.r}`);
  log('→', C.d, `Input: ${inputSize} bytes`, `peers: ${status.peers}`);
  log('→', C.d, `WASM module: add.wasm (${DEMO_WASM.length} bytes)`);
  console.log();

  const startTime = Date.now();

  try {
    // Phase 1: Negotiation
    log('◌', C.blue, 'Phase 1: Negotiating with mesh...');

    const result = await node.compute(DEMO_WASM, inputData, {
      entryPoint: 'add',
      deadline: 10000,
    });

    const elapsed = Date.now() - startTime;

    console.log();
    if (result.localFallback) {
      log('⚠', C.yellow, `${C.b}LOCAL FALLBACK${C.r} — no executor responded, ran locally`);
    } else {
      log('✓', C.green, `${C.b}MESH COMPUTE COMPLETE${C.r}`);
    }

    console.log();
    console.log(`  ${C.d}${'─'.repeat(44)}${C.r}`);
    console.log(`  ${C.d}Total Time       ${C.r}${C.b}${elapsed}ms${C.r}`);
    console.log(`  ${C.d}Chunks           ${C.r}${C.b}${result.chunksExecuted}${C.r}`);
    console.log(`  ${C.d}Devices Used     ${C.r}${C.b}${result.devicesUsed}${C.r}`);
    console.log(`  ${C.d}Output Size      ${C.r}${C.b}${result.data.length} bytes${C.r}`);
    console.log(`  ${C.d}Verified         ${C.r}${result.verified ? `${C.green}Yes` : `${C.red}No`}${C.r}`);
    console.log(`  ${C.d}Local Fallback   ${C.r}${result.localFallback ? `${C.yellow}Yes` : `${C.green}No`}${C.r}`);
    console.log(`  ${C.d}${'─'.repeat(44)}${C.r}`);
    console.log();

    // Show first/last bytes of output
    if (result.data.length > 0) {
      const preview = Array.from(result.data.slice(0, 16))
        .map(b => b.toString(16).padStart(2, '0'))
        .join(' ');
      log('◈', C.d, `Output preview: ${preview}${result.data.length > 16 ? ' ...' : ''}`);
    }

  } catch (err: any) {
    log('✗', C.red, `Compute failed: ${err.message}`);
  }

  console.log();
}

// ══════════════════════════════════════════════════
// PEERS: Show connected peers
// ══════════════════════════════════════════════════

function doPeers(node: CMPNode): void {
  const peers = node.getPeers();
  console.log();

  if (peers.length === 0) {
    log('◌', C.d, 'No peers connected');
    console.log(`  ${C.d}Start another node: npx tsx src/cli.ts start${C.r}`);
  } else {
    log('◆', C.cyan, `${C.b}${peers.length}${C.r} connected peers:`);
    console.log();
    console.log(`  ${C.b}${'ID'.padEnd(10)}${'State'.padEnd(10)}${'Tier'.padEnd(6)}${'Cores'.padEnd(8)}${'Memory'.padEnd(10)}${'Transport'.padEnd(12)}${C.r}`);
    console.log(`  ${C.d}${'─'.repeat(54)}${C.r}`);

    for (const p of peers) {
      const mem = p.memoryMb ? (p.memoryMb < 1024 ? `${p.memoryMb}MB` : `${(p.memoryMb / 1024).toFixed(1)}GB`) : '?';
      console.log(
        `  ${p.shortId.padEnd(10)}` +
        `${C.green}${p.state.padEnd(10)}${C.r}` +
        `T${(p.tier || '?').toString().padEnd(5)}` +
        `${(p.cores?.toString() || '?').padEnd(8)}` +
        `${mem.padEnd(10)}` +
        `${p.transports.join(',')}`
      );
    }
  }
  console.log();
}

// ══════════════════════════════════════════════════
// STATUS: Show mesh status
// ══════════════════════════════════════════════════

function doStatus(node: CMPNode): void {
  const s = node.getStatus();
  const uptime = Math.floor(s.uptime / 1000);
  const uptimeStr = uptime < 60 ? `${uptime}s` : `${Math.floor(uptime / 60)}m ${uptime % 60}s`;

  console.log();
  console.log(`  ${C.d}${'─'.repeat(40)}${C.r}`);
  console.log(`  ${C.d}Node ID          ${C.r}${C.b}${s.meshId.substring(0, 16)}...${C.r}`);
  console.log(`  ${C.d}Running          ${C.r}${s.running ? `${C.green}Yes` : `${C.red}No`}${C.r}`);
  console.log(`  ${C.d}Uptime           ${C.r}${uptimeStr}`);
  console.log(`  ${C.d}Peers            ${C.r}${C.b}${s.peers}${C.r}`);
  console.log(`  ${C.d}Mesh Cores       ${C.r}${C.b}${s.resources.totalCores}${C.r}`);
  console.log(`  ${C.d}Mesh Memory      ${C.r}${C.b}${s.resources.totalMemoryMb < 1024 ? s.resources.totalMemoryMb + ' MB' : (s.resources.totalMemoryMb / 1024).toFixed(1) + ' GB'}${C.r}`);
  console.log(`  ${C.d}GPU Devices      ${C.r}${s.resources.gpuDevices}`);
  console.log(`  ${C.d}Credits          ${C.r}${s.credits} CCU`);
  console.log(`  ${C.d}${'─'.repeat(40)}${C.r}`);
  console.log();
}

// ══════════════════════════════════════════════════
// BENCH: Quick benchmark
// ══════════════════════════════════════════════════

async function cmdBench(): Promise<void> {
  banner();
  log('◌', C.cyan, 'Running 5-node virtual mesh benchmark...');
  console.log();

  Logger.setLevel(LogLevel.WARN);

  const { VirtualNetwork, VirtualTransport } = await import('../../transport/src/virtual-transport');
  const network = new VirtualNetwork();
  const nodes: CMPNode[] = [];

  const t0 = Date.now();

  for (let i = 0; i < 5; i++) {
    const transport = new VirtualTransport(`bench-${i}`, network);
    nodes.push(new CMPNode({ _transport: transport, beaconIntervalMs: 100, bidWindowMs: 300, logLevel: LogLevel.WARN }));
  }

  for (const n of nodes) await n.start();
  await new Promise(r => setTimeout(r, 2000));

  const meshTime = Date.now() - t0;
  const peers = nodes[0].getStatus().peers;
  const res = nodes[0].getStatus().resources;

  log('✓', C.green, `Mesh formed: ${meshTime}ms`, `${peers} peers, ${res.totalCores} cores`);

  const t1 = Date.now();
  const result = await nodes[0].compute(DEMO_WASM, new Uint8Array(1024), { entryPoint: 'add', deadline: 5000 });
  const computeTime = Date.now() - t1;

  log('✓', C.green, `Compute: ${computeTime}ms`, `${result.chunksExecuted} chunks, ${result.devicesUsed} devices`);

  for (const n of nodes) await n.stop();

  console.log();
  console.log(`  ${C.d}${'─'.repeat(35)}${C.r}`);
  console.log(`  ${C.d}Mesh Formation   ${C.r}${C.b}${meshTime}ms${C.r}`);
  console.log(`  ${C.d}Compute          ${C.r}${C.b}${computeTime}ms${C.r}`);
  console.log(`  ${C.d}Total            ${C.r}${C.b}${Date.now() - t0}ms${C.r}`);
  console.log(`  ${C.d}${'─'.repeat(35)}${C.r}`);
  console.log();
}

// ══════════════════════════════════════════════════
// VERSION / HELP
// ══════════════════════════════════════════════════

function cmdVersion(): void {
  console.log(`  CMP v${VERSION} — Compute Mesh Protocol — Agent Viscro`);
}

function cmdHelp(): void {
  banner();
  console.log(`  ${C.b}Usage:${C.r}`);
  console.log(`    ${C.cyan}npx tsx src/cli.ts start${C.r}        Start a node (interactive)`);
  console.log(`      --share <pct>              Resource share % (default: 50)`);
  console.log(`      --verbose                  Show all protocol logs`);
  console.log();
  console.log(`    ${C.cyan}npx tsx src/cli.ts bench${C.r}        Run 5-node benchmark`);
  console.log(`    ${C.cyan}npx tsx src/cli.ts version${C.r}      Show version`);
  console.log(`    ${C.cyan}npx tsx src/cli.ts help${C.r}         Show this help`);
  console.log();
  console.log(`  ${C.b}Interactive commands (after 'start'):${C.r}`);
  console.log(`    ${C.cyan}compute${C.r}   Send a task to the mesh`);
  console.log(`    ${C.cyan}peers${C.r}     Show connected peers`);
  console.log(`    ${C.cyan}status${C.r}    Show mesh status`);
  console.log(`    ${C.cyan}quit${C.r}      Shutdown`);
  console.log();
}

// ══════════════════════════════════════════════════
// MAIN
// ══════════════════════════════════════════════════

async function main(): Promise<void> {
  try {
    switch (command) {
      case 'start': await cmdStart(); break;
      case 'bench': await cmdBench(); break;
      case 'version': case '-v': case '--version': cmdVersion(); break;
      case 'help': case '-h': case '--help': default: cmdHelp(); break;
    }
  } catch (err: any) {
    console.error(`\n  ${C.red}Error: ${err.message}${C.r}\n`);
    process.exit(1);
  }
}

main();
